# The quantity the old flat wholesale_price is parked at. The old field carried
# no threshold of its own — it applied whenever a cashier flagged the whole
# order "Wholesale" — so migrating it needs a number invented for it. 10 is a
# holding value the Owner is expected to edit per product, not a rule; what it
# must not be is 1, which would hand every walk-in buying a single unit the
# bulk price and quietly wipe out retail margin.
LEGACY_TIER_MIN_QUANTITY = 10


def wholesale_price_to_tier(apps, schema_editor):
    Product = apps.get_model('inventory', 'Product')
    ProductPriceTier = apps.get_model('inventory', 'ProductPriceTier')
    ProductPriceTier.objects.bulk_create([
        ProductPriceTier(
            product=product,
            min_quantity=LEGACY_TIER_MIN_QUANTITY,
            unit_price=product.wholesale_price,
        )
        for product in Product.objects.exclude(wholesale_price=None).filter(
            wholesale_price__gt=0
        )
    ])


def tier_to_wholesale_price(apps, schema_editor):
    Product = apps.get_model('inventory', 'Product')
    ProductPriceTier = apps.get_model('inventory', 'ProductPriceTier')
    for tier in ProductPriceTier.objects.filter(
        min_quantity=LEGACY_TIER_MIN_QUANTITY
    ).select_related('product'):
        Product.objects.filter(pk=tier.product_id).update(
            wholesale_price=tier.unit_price
        )


